import org.joget.apps.app.service.AppPluginUtil;
import org.joget.plugin.base.ApplicationPlugin;
import org.joget.plugin.property.model.PropertyEditable;
import org.joget.apps.app.model.AppDefinition;
import javax.servlet.http.HttpServletRequest;
import java.sql.*;
import java.util.Map;
import javax.sql.DataSource;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import javax.mail.Transport;
import org.joget.apps.app.model.AppDefinition;
import org.joget.apps.app.service.AppUtil;
import org.joget.plugin.base.Plugin;
import org.joget.commons.util.LogUtil;




    public Object sendMail(AppDefinition appDef, HttpServletRequest request, String email, String subject, String emailContent) {
        try {
            // Replace line breaks in the subject
            subject = subject.replace("\n", " ").replace("\r", "");

            Plugin plugin = pluginManager.getPlugin("org.joget.apps.app.lib.EmailTool");

            Map propertiesMap = AppPluginUtil.getDefaultProperties(plugin, null, appDef, null);
            propertiesMap.put("pluginManager", pluginManager);
            propertiesMap.put("appDef", appDef);
            propertiesMap.put("request", request);

            ApplicationPlugin emailTool = (ApplicationPlugin) plugin;

            propertiesMap.put("toSpecific", email);
            propertiesMap.put("subject", subject);
            propertiesMap.put("message", emailContent);

            ((PropertyEditable) emailTool).setProperties(propertiesMap);
            emailTool.execute(propertiesMap);

        } catch (Exception e) {
            LogUtil.error("SendMailTask", e, "Failed to send email.");
        }
        return null;
    }


        String id = "#form.actualites_dir.id#";
        String envoyer_par_mail = "#form.actualites_dir.envoyer_par_mail#";
        String subject = "";
        String emailContent = "";
        String emails = "";


        if ("Oui".equals(envoyer_par_mail)) {
            try  {
                Connection con = ((DataSource) AppUtil.getApplicationContext().getBean("setupDataSource")).getConnection();
                if (!con.isClosed()) {
                    // Fetch subject and email content
                    String sqlActualites = "SELECT c_titre, c_article FROM jwdb.app_fd_actualites_dir WHERE id = ?";
                  
                        PreparedStatement stmt = con.prepareStatement(sqlActualites);
                        stmt.setString(1, id);
                        ResultSet rs = stmt.executeQuery();
                            if (rs.next()) {
                                subject = rs.getString(1);
                                emailContent = rs.getString(2);
                            }
                        
                    

                    // Fetch recipient emails
                    String sqlEmails = "SELECT c_adresse_electronique_directeur FROM app_fd_directeurs WHERE c_active = 1";
                    PreparedStatement stmt = con.prepareStatement(sqlEmails);
                         ResultSet rs = stmt.executeQuery(); 
                        while (rs.next()) {
                            emails = rs.getString(1);
                            sendMail(appDef, request, emails, subject, emailContent);
                        }
                    
                }
            } catch (Exception e) {
                LogUtil.error("SendMailTask", e, "Error executing mail task.");
            }
        }
